import '@tanstack/react-table'
import type { RowData } from '@tanstack/react-table'

export type FilterVariant =
  | 'text'
  | 'number'
  | 'dateRange'
  | 'select'
  | 'multiSelect'

export interface FilterOption {
  label: string
  value: string
}

// Module augmentation: adds `label`/`filterVariant`/`filterOptions` to every
// column's `meta` so FilterToolbar and useActiveFilters can read them without
// per-column wiring. TData/TValue must be re-declared to match TanStack's
// own signature or the merge is silently ignored.
declare module '@tanstack/react-table' {
  interface ColumnMeta<TData extends RowData, TValue> {
    label: string
    filterVariant?: FilterVariant
    filterOptions?: FilterOption[]
  }
}

import type { FilterFn } from '@tanstack/react-table'
import type { DateRange } from 'react-day-picker'

export interface FilterConditionValue {
  operator: string
  value: unknown
}

// One filterFn for every filterable column, regardless of variant — the
// comparison it runs is chosen by `filterValue.operator`, not by which
// column it's attached to. TData isn't used in the body, so `any` here
// doesn't lose real type safety.
export const conditionFilterFn: FilterFn<any> = (
  row,
  columnId,
  filterValue: FilterConditionValue | undefined,
) => {
  if (!filterValue?.operator) return true
  const cellValue = row.getValue(columnId)
  return evaluateOperator(filterValue.operator, cellValue, filterValue.value)
}
conditionFilterFn.autoRemove = (value: FilterConditionValue | undefined) =>
  !value?.operator

function evaluateOperator(
  operator: string,
  cellValue: unknown,
  filterValue: unknown,
): boolean {
  switch (operator) {
    case 'contains':
      return (
        typeof cellValue === 'string' &&
        cellValue.toLowerCase().includes(String(filterValue ?? '').toLowerCase())
      )
    case 'notContains':
      return (
        typeof cellValue === 'string' &&
        !cellValue.toLowerCase().includes(String(filterValue ?? '').toLowerCase())
      )
    case 'is':
      return cellValue === filterValue
    case 'isNot':
      return cellValue !== filterValue
    case 'eq':
      return Number(cellValue) === Number(filterValue)
    case 'neq':
      return Number(cellValue) !== Number(filterValue)
    case 'gt':
      return Number(cellValue) > Number(filterValue)
    case 'gte':
      return Number(cellValue) >= Number(filterValue)
    case 'lt':
      return Number(cellValue) < Number(filterValue)
    case 'lte':
      return Number(cellValue) <= Number(filterValue)
    case 'isAnyOf':
      return Array.isArray(filterValue) && filterValue.includes(cellValue)
    case 'isNoneOf':
      return Array.isArray(filterValue) && !filterValue.includes(cellValue)
    case 'isBetween': {
      const range = filterValue as DateRange | undefined
      const date = cellValue as Date
      if (range?.from && date < range.from) return false
      if (range?.to && date > range.to) return false
      return true
    }
    case 'isEmpty':
      return cellValue === undefined || cellValue === null || cellValue === ''
    case 'isNotEmpty':
      return !(cellValue === undefined || cellValue === null || cellValue === '')
    default:
      return true
  }
}

'use client'

import { format } from 'date-fns'
import { CalendarIcon } from 'lucide-react'

import type { DateRange } from 'react-day-picker'

import { Button } from '#/components/ui/button'
import { Calendar } from '#/components/ui/calendar'
import {
  Popover,
  PopoverContent,
  PopoverTrigger,
} from '#/components/ui/popover'

export interface DateRangeFilterProps {
  label: string
  value: DateRange | undefined
  onChange: (value: DateRange | undefined) => void
}

export function DateRangeFilter({
  label,
  value,
  onChange,
}: DateRangeFilterProps) {
  return (
    <Popover>
      <PopoverTrigger asChild>
        <Button variant="outline" size="sm">
          <CalendarIcon className="mr-2 h-4 w-4" />
          {value?.from ? (
            value.to ? (
              <>
                {format(value.from, 'MMM d')} – {format(value.to, 'MMM d')}
              </>
            ) : (
              format(value.from, 'MMM d')
            )
          ) : (
            label
          )}
        </Button>
      </PopoverTrigger>
      <PopoverContent className="w-auto p-0" align="start">
        <Calendar
          mode="range"
          defaultMonth={value?.from}
          selected={value}
          onSelect={onChange}
          numberOfMonths={2}
        />
      </PopoverContent>
    </Popover>
  )
}

'use client'

import type { DateRange } from 'react-day-picker'

import { Input } from '#/components/ui/input'
import {
  Select,
  SelectContent,
  SelectGroup,
  SelectItem,
  SelectTrigger,
  SelectValue,
} from '#/components/ui/select'
import { MultiSelectFilter } from '#/components/ui/multiple-select-filter'
import { DateRangeFilter } from './date-range-filter'
import type { OperatorDef } from './operators'
import type { FilterOption, FilterVariant } from './types'

export interface FilterValueInputProps {
  label: string
  variant: FilterVariant
  operator: OperatorDef
  options?: FilterOption[]
  value: unknown
  onChange: (value: unknown) => void
}

/**
 * Renders the value control for a condition's valueShape/variant pair.
 * `operator.valueShape` decides whether anything renders at all ("is empty"
 * needs no value); `variant` decides which control fills a given shape,
 * reusing the same DateRangeFilter/MultiSelectFilter used elsewhere.
 */
export function FilterValueInput({
  label,
  variant,
  operator,
  options,
  value,
  onChange,
}: FilterValueInputProps) {
  if (operator.valueShape === 'none') return null

  switch (variant) {
    case 'text':
      return (
        <Input
          autoFocus
          placeholder="Value"
          value={(value as string | undefined) ?? ''}
          onChange={(e) => onChange(e.target.value)}
          className="w-full"
        />
      )

    case 'number':
      return (
        <Input
          autoFocus
          type="number"
          placeholder="Value"
          value={(value as number | undefined) ?? ''}
          onChange={(e) =>
            onChange(e.target.value === '' ? undefined : e.target.valueAsNumber)
          }
          className="w-full"
        />
      )

    case 'select':
      return (
        <Select
          value={(value as string | undefined) ?? ''}
          onValueChange={onChange}
        >
          <SelectTrigger className="w-full">
            <SelectValue placeholder="Select value" />
          </SelectTrigger>
          <SelectContent>
            <SelectGroup>
              {options?.map((option) => (
                <SelectItem key={option.value} value={option.value}>
                  {option.label}
                </SelectItem>
              ))}
            </SelectGroup>
          </SelectContent>
        </Select>
      )

    case 'multiSelect':
      return (
        <MultiSelectFilter
          title={label}
          options={options ?? []}
          selected={(value as string[] | undefined) ?? []}
          onChange={onChange}
        />
      )

    case 'dateRange':
      return (
        <DateRangeFilter
          label={label}
          value={value as DateRange | undefined}
          onChange={onChange}
        />
      )
  }
}

'use client'

import { useState } from 'react'

import type { Table } from '@tanstack/react-table'

import { Button } from '#/components/ui/button'
import {
  Command,
  CommandEmpty,
  CommandGroup,
  CommandInput,
  CommandItem,
  CommandList,
} from '#/components/ui/command'
import {
  Select,
  SelectContent,
  SelectGroup,
  SelectItem,
  SelectTrigger,
  SelectValue,
} from '#/components/ui/select'
import { FilterValueInput } from './filter-value-input'
import { isValueValid, operatorRegistry } from './operators'
import './types'

export interface FilterConditionEditorProps<TData> {
  table: Table<TData>
  /** Locked column — present when editing an existing condition. */
  columnId?: string
  /** Columns selectable in the "pick a column" step (add mode only). */
  availableColumnIds?: string[]
  initialOperator?: string
  initialValue?: unknown
  onApply: (columnId: string, operator: string, value: unknown) => void
  /** Present only in edit mode. */
  onRemove?: () => void
}

export function FilterConditionEditor<TData>({
  table,
  columnId: lockedColumnId,
  availableColumnIds = [],
  initialOperator,
  initialValue,
  onApply,
  onRemove,
}: FilterConditionEditorProps<TData>) {
  const [columnId, setColumnId] = useState<string | undefined>(lockedColumnId)
  const [operator, setOperator] = useState<string | undefined>(initialOperator)
  const [value, setValue] = useState<unknown>(initialValue)

  const meta = columnId ? table.getColumn(columnId)?.columnDef.meta : undefined
  const operators = meta?.filterVariant ? operatorRegistry[meta.filterVariant] : []
  const activeOperator = operators.find((o) => o.value === operator)

  function selectColumn(id: string) {
    const nextMeta = table.getColumn(id)?.columnDef.meta
    const nextOperators = nextMeta?.filterVariant
      ? operatorRegistry[nextMeta.filterVariant]
      : []
    setColumnId(id)
    setOperator(nextOperators[0]?.value)
    setValue(undefined)
  }

  // Step 1: no column locked and none picked yet — choose which column to filter.
  if (!lockedColumnId && !columnId) {
    return (
      <Command>
        <CommandInput placeholder="Filter by..." />
        <CommandList>
          <CommandEmpty>No more columns to filter.</CommandEmpty>
          <CommandGroup>
            {availableColumnIds.map((id) => (
              <CommandItem key={id} onSelect={() => selectColumn(id)}>
                {table.getColumn(id)?.columnDef.meta?.label}
              </CommandItem>
            ))}
          </CommandGroup>
        </CommandList>
      </Command>
    )
  }

  if (!columnId || !meta?.filterVariant) return null

  // Step 2: column is set — choose operator, then the matching value input.
  return (
    <div className="space-y-3 p-3">
      <p className="text-sm font-medium text-foreground">{meta.label}</p>

      <Select value={operator} onValueChange={setOperator}>
        <SelectTrigger className="w-full">
          <SelectValue placeholder="Operator" />
        </SelectTrigger>
        <SelectContent>
          <SelectGroup>
            {operators.map((op) => (
              <SelectItem key={op.value} value={op.value}>
                {op.label}
              </SelectItem>
            ))}
          </SelectGroup>
        </SelectContent>
      </Select>

      {activeOperator && (
        <FilterValueInput
          label={meta.label}
          variant={meta.filterVariant}
          operator={activeOperator}
          options={meta.filterOptions}
          value={value}
          onChange={setValue}
        />
      )}

      <div className="flex items-center justify-between pt-1">
        {onRemove ? (
          <Button type="button" variant="ghost" size="sm" onClick={onRemove}>
            Remove
          </Button>
        ) : (
          <span />
        )}
        <Button
          type="button"
          size="sm"
          disabled={!activeOperator || !isValueValid(activeOperator, value)}
          onClick={() => activeOperator && onApply(columnId, activeOperator.value, value)}
        >
          Apply
        </Button>
      </div>
    </div>
  )
}

'use client'

import { useState } from 'react'
import { Plus } from 'lucide-react'

import type { Table } from '@tanstack/react-table'

import { Button } from '#/components/ui/button'
import {
  Popover,
  PopoverContent,
  PopoverTrigger,
} from '#/components/ui/popover'
import { FilterConditionEditor } from './filter-condition-editor'
import { formatConditionValue, operatorRegistry } from './operators'
import type { FilterCondition } from './operators'
import { useFilterConditions } from './use-filter-conditions'
import './types'

export interface FilterToolbarProps<TData> {
  table: Table<TData>
}

export function FilterToolbar<TData>({ table }: FilterToolbarProps<TData>) {
  const conditions = useFilterConditions(table)
  const filterableColumns = table
    .getAllColumns()
    .filter((column) => column.columnDef.meta?.filterVariant)

  if (filterableColumns.length === 0) return null

  const activeColumnIds = new Set(conditions.map((c) => c.columnId))
  const availableColumnIds = filterableColumns
    .filter((column) => !activeColumnIds.has(column.id))
    .map((column) => column.id)

  return (
    <div className="flex flex-wrap items-center gap-2">
      {conditions.map((condition) => (
        <FilterConditionPill
          key={condition.columnId}
          table={table}
          condition={condition}
        />
      ))}

      {availableColumnIds.length > 0 && (
        <AddFilterTrigger table={table} availableColumnIds={availableColumnIds} />
      )}
    </div>
  )
}

function AddFilterTrigger<TData>({
  table,
  availableColumnIds,
}: {
  table: Table<TData>
  availableColumnIds: string[]
}) {
  const [open, setOpen] = useState(false)

  return (
    <Popover open={open} onOpenChange={setOpen}>
      <PopoverTrigger asChild>
        <Button type="button" variant="outline" size="sm">
          <Plus className="h-4 w-4" />
          Add filter
        </Button>
      </PopoverTrigger>
      <PopoverContent className="w-64 p-0" align="start">
        <FilterConditionEditor
          table={table}
          availableColumnIds={availableColumnIds}
          onApply={(columnId, operator, value) => {
            table.getColumn(columnId)?.setFilterValue({ operator, value })
            setOpen(false)
          }}
        />
      </PopoverContent>
    </Popover>
  )
}

function FilterConditionPill<TData>({
  table,
  condition,
}: {
  table: Table<TData>
  condition: FilterCondition
}) {
  const [open, setOpen] = useState(false)
  const meta = table.getColumn(condition.columnId)?.columnDef.meta
  const operators = meta?.filterVariant ? operatorRegistry[meta.filterVariant] : []
  const activeOperator = operators.find((o) => o.value === condition.operator)

  if (!meta?.filterVariant) return null

  const valueDisplay = formatConditionValue(
    meta.filterVariant,
    activeOperator,
    condition.value,
    meta.filterOptions,
  )

  return (
    <Popover open={open} onOpenChange={setOpen}>
      <PopoverTrigger asChild>
        <Button type="button" variant="outline" size="sm">
          <span>{meta.label}</span>
          <span className="text-muted-foreground">{activeOperator?.label}</span>
          {valueDisplay && <span className="font-medium">{valueDisplay}</span>}
        </Button>
      </PopoverTrigger>
      <PopoverContent className="w-64 p-0" align="start">
        <FilterConditionEditor
          table={table}
          columnId={condition.columnId}
          initialOperator={condition.operator}
          initialValue={condition.value}
          onApply={(columnId, operator, value) => {
            table.getColumn(columnId)?.setFilterValue({ operator, value })
            setOpen(false)
          }}
          onRemove={() => {
            table.getColumn(condition.columnId)?.setFilterValue(undefined)
            setOpen(false)
          }}
        />
      </PopoverContent>
    </Popover>
  )
}

import { useMemo } from 'react'

import type { Table } from '@tanstack/react-table'

import type { FilterConditionValue } from './filter-fns'
import type { FilterCondition } from './operators'
import './types'

/**
 * Reads FilterCondition[] straight from `table.getState().columnFilters` —
 * columnFilters (keyed by columnId, valued `{ operator, value }`) is the one
 * source of truth. There's nowhere else a condition could live, so the
 * toolbar pills, the "+ Add filter" menu, and the chips row can never drift
 * out of sync with each other.
 */
export function useFilterConditions<TData>(
  table: Table<TData>,
): FilterCondition[] {
  const columnFilters = table.getState().columnFilters

  return useMemo(() => {
    const conditions: FilterCondition[] = []

    for (const filter of columnFilters) {
      const meta = table.getColumn(filter.id)?.columnDef.meta
      if (!meta?.filterVariant) continue

      const raw = filter.value as FilterConditionValue | undefined
      if (!raw?.operator) continue

      conditions.push({
        id: filter.id,
        columnId: filter.id,
        operator: raw.operator,
        value: raw.value,
      })
    }

    return conditions
  }, [columnFilters, table])
}

import { useMemo } from 'react'

import type { Table } from '@tanstack/react-table'

import { formatConditionValue, operatorRegistry } from './operators'
import { useFilterConditions } from './use-filter-conditions'
import './types'

export interface ActiveFilterEntry {
  columnId: string
  label: string
  /** "{operator label} {value}", e.g. "is any of Design, Engineering". */
  display: string
}

export function useActiveFilters<TData>(
  table: Table<TData>,
): ActiveFilterEntry[] {
  const conditions = useFilterConditions(table)

  return useMemo(() => {
    const entries: ActiveFilterEntry[] = []

    for (const condition of conditions) {
      const meta = table.getColumn(condition.columnId)?.columnDef.meta
      if (!meta?.filterVariant) continue

      const operator = operatorRegistry[meta.filterVariant].find(
        (o) => o.value === condition.operator,
      )
      if (!operator) continue

      const valueDisplay = formatConditionValue(
        meta.filterVariant,
        operator,
        condition.value,
        meta.filterOptions,
      )

      entries.push({
        columnId: condition.columnId,
        label: meta.label,
        display: valueDisplay
          ? `${operator.label} ${valueDisplay}`
          : operator.label,
      })
    }

    return entries
  }, [conditions, table])
}

'use client'

import { X } from 'lucide-react'

import type { Table } from '@tanstack/react-table'

import { Badge } from '#/components/ui/badge'
import { Button } from '#/components/ui/button'
import { useActiveFilters } from './use-active-filters'

export interface ActiveFilterChipsProps<TData> {
  table: Table<TData>
}

export function ActiveFilterChips<TData>({
  table,
}: ActiveFilterChipsProps<TData>) {
  const activeFilters = useActiveFilters(table)

  if (activeFilters.length === 0) return null

  return (
    <div className="flex flex-wrap items-center gap-2">
      {activeFilters.map((filter) => (
        <Badge key={filter.columnId} variant="secondary" className="gap-1 pr-1">
          {filter.label} {filter.display}
          <button
            type="button"
            onClick={() =>
              table.getColumn(filter.columnId)?.setFilterValue(undefined)
            }
            aria-label={`Remove ${filter.label} filter`}
          >
            <X className="h-3 w-3" />
          </button>
        </Badge>
      ))}
      <Button variant="ghost" size="sm" onClick={() => table.resetColumnFilters()}>
        Clear all
      </Button>
    </div>
  )
}

'use client'

import { format } from 'date-fns'
import {
  flexRender,
  getCoreRowModel,
  getFilteredRowModel,
  useReactTable,
} from '@tanstack/react-table'

import type { ColumnDef } from '@tanstack/react-table'

import {
  Table,
  TableBody,
  TableCell,
  TableHead,
  TableHeader,
  TableRow,
} from '#/components/ui/table'
import { FilterToolbar } from './filter-toolbar'
import { ActiveFilterChips } from './active-filter-chips'
import { conditionFilterFn } from './filter-fns'
import './types'

type Task = {
  id: string
  title: string
  category: string
  dueDate: Date
}

const data: Task[] = [
  { id: 'tsk-1', title: 'Redesign onboarding flow', category: 'Design', dueDate: new Date('2026-08-05') },
  { id: 'tsk-2', title: 'Fix pagination bug on export', category: 'Engineering', dueDate: new Date('2026-08-08') },
  { id: 'tsk-3', title: 'Write Q3 newsletter draft', category: 'Marketing', dueDate: new Date('2026-07-28') },
  { id: 'tsk-4', title: 'Audit component color tokens', category: 'Design', dueDate: new Date('2026-08-15') },
  { id: 'tsk-5', title: 'Migrate auth to new session store', category: 'Engineering', dueDate: new Date('2026-08-20') },
]

// Three variants, config-driven — no per-column filter wiring beyond `meta`.
// Every filterable column shares the same generic `conditionFilterFn`; the
// operator on the active condition (not the column) decides the comparison.
const columns: ColumnDef<Task>[] = [
  {
    accessorKey: 'title',
    header: 'Title',
    filterFn: conditionFilterFn,
    meta: {
      label: 'Title',
      filterVariant: 'text',
    },
  },
  {
    accessorKey: 'category',
    header: 'Category',
    filterFn: conditionFilterFn,
    meta: {
      label: 'Category',
      filterVariant: 'multiSelect',
      filterOptions: [
        { label: 'Design', value: 'Design' },
        { label: 'Engineering', value: 'Engineering' },
        { label: 'Marketing', value: 'Marketing' },
      ],
    },
  },
  {
    accessorKey: 'dueDate',
    header: 'Due date',
    filterFn: conditionFilterFn,
    cell: ({ getValue }) => format(getValue<Date>(), 'MMM d, yyyy'),
    meta: {
      label: 'Due date',
      filterVariant: 'dateRange',
    },
  },
]

export function FilterToolbarDemo() {
  const table = useReactTable({
    data,
    columns,
    getCoreRowModel: getCoreRowModel(),
    getFilteredRowModel: getFilteredRowModel(),
  })

  return (
    <div>
      <div className="mb-3 flex flex-wrap items-center justify-between gap-2">
        <FilterToolbar table={table} />
      </div>

      <div className="mb-3">
        <ActiveFilterChips table={table} />
      </div>

      <div className="overflow-hidden rounded-md border">
        <Table>
          <TableHeader>
            {table.getHeaderGroups().map((headerGroup) => (
              <TableRow key={headerGroup.id}>
                {headerGroup.headers.map((header) => (
                  <TableHead key={header.id}>
                    {header.isPlaceholder
                      ? null
                      : flexRender(
                          header.column.columnDef.header,
                          header.getContext(),
                        )}
                  </TableHead>
                ))}
              </TableRow>
            ))}
          </TableHeader>
          <TableBody>
            {table.getRowModel().rows.length ? (
              table.getRowModel().rows.map((row) => (
                <TableRow key={row.id}>
                  {row.getVisibleCells().map((cell) => (
                    <TableCell key={cell.id}>
                      {flexRender(
                        cell.column.columnDef.cell,
                        cell.getContext(),
                      )}
                    </TableCell>
                  ))}
                </TableRow>
              ))
            ) : (
              <TableRow>
                <TableCell colSpan={columns.length} className="h-24 text-center">
                  No results.
                </TableCell>
              </TableRow>
            )}
          </TableBody>
        </Table>
      </div>
    </div>
  )
}

import { PlusCircle } from "lucide-react";
import { Button } from "./button";
import { Popover, PopoverContent, PopoverTrigger } from "./popover";
import { Badge } from "./badge";
import { Command, CommandGroup, CommandInput, CommandItem, CommandList } from "./command";
import { Checkbox } from "./checkbox";

export function MultiSelectFilter({
  title,
  options,
  selected,
  onChange,
}: {
  title: string;
  options: { label: string; value: string; count?: number }[];
  selected: string[];
  onChange: (values: string[]) => void;
}) {
  return (
    <Popover>
      <PopoverTrigger asChild>
        <Button variant="outline" size="sm">
          <PlusCircle className="mr-2 h-4 w-4" />
          {title}
          {selected.length > 0 && (
            <Badge variant="secondary" className="ml-2">
              {selected.length}
            </Badge>
          )}
        </Button>
      </PopoverTrigger>
      <PopoverContent className="w-[200px] p-0" align="start">
        <Command>
          <CommandInput placeholder={title} />
          <CommandList>
            <CommandGroup>
              {options.map((option) => {
                const isSelected = selected.includes(option.value);
                return (
                  <CommandItem
                    key={option.value}
                    onSelect={() => {
                      onChange(
                        isSelected
                          ? selected.filter((v) => v !== option.value)
                          : [...selected, option.value]
                      );
                    }}
                  >
                    <Checkbox checked={isSelected} className="mr-2" />
                    <span>{option.label}</span>
                    {option.count !== undefined && (
                      <span className="ml-auto text-muted-foreground text-xs">
                        {option.count}
                      </span>
                    )}
                  </CommandItem>
                );
              })}
            </CommandGroup>
          </CommandList>
        </Command>
      </PopoverContent>
    </Popover>
  );
}
